// Flag pages whose clicks dropped past the threshold versus the previous window.
const cfg = $('Set GSC and WP Config').first().json;
const DAY = 86400000;
const now = Date.now();

// Never re-flag pages with an open brief, and respect the cooldown for the rest
const blocked = new Set();
for (const row of $('Read Log from Google Sheets').all()) {
  const url = String(row.json.page_url ?? '').trim();
  if (!url) continue;
  const status = String(row.json.status ?? '').trim().toLowerCase();
  const detected = Date.parse(row.json.detected_at);
  if (['pending', 'refreshed'].includes(status) || isNaN(detected) || now - detected < cfg.cooldown_days * DAY) {
    blocked.add(url);
  }
}

const base = new URL(cfg.wp_base_url).hostname.replace(/^www\./, '');
const current = {};
for (const r of $('Post Current Period Pages').first().json.rows ?? []) current[r.keys[0]] = r;

const candidates = [];
for (const prev of $('Post Previous Period Pages').first().json.rows ?? []) {
  const pageUrl = prev.keys[0];
  let parsed;
  try { parsed = new URL(pageUrl); } catch { continue; }
  if (parsed.hostname.replace(/^www\./, '') !== base || parsed.hash || parsed.search) continue;
  const segments = parsed.pathname.split('/').filter(Boolean);
  if (segments.length === 0 || blocked.has(pageUrl)) continue;
  if (prev.clicks < cfg.min_prev_clicks) continue;

  const cur = current[pageUrl] ?? { clicks: 0, impressions: 0, position: null };
  const change = (cur.clicks - prev.clicks) / prev.clicks;
  if (change > -cfg.drop_threshold) continue;

  candidates.push({
    page_url: pageUrl,
    path: decodeURIComponent(parsed.pathname).replace(/\/+$/, '').toLowerCase(),
    slug: decodeURIComponent(segments[segments.length - 1]),
    clicks_prev: prev.clicks,
    clicks_now: cur.clicks,
    click_change: `${(change * 100).toFixed(1)}%`,
    lost_clicks: prev.clicks - cur.clicks,
    impressions_prev: prev.impressions,
    impressions_now: cur.impressions,
    position_prev: Number(prev.position.toFixed(1)),
    position_now: cur.position == null ? '' : Number(cur.position.toFixed(1)),
  });
}

candidates.sort((a, b) => b.lost_clicks - a.lost_clicks);
return candidates
  .slice(0, Number(cfg.max_per_run))
  .map((json) => ({ json, pairedItem: { item: 0 } }));

// Match decaying pages to WordPress posts/pages by URL path.
const normalize = (u) => {
  try { return decodeURIComponent(new URL(u).pathname).replace(/\/+$/, '').toLowerCase(); }
  catch { return ''; }
};

const index = {};
for (const [nodeName, restBase] of [['Get WP Posts by Slug', 'posts'], ['Get WP Pages by Slug', 'pages']]) {
  for (const item of $(nodeName).all()) {
    const j = item.json;
    if (!j || j.error || !j.id || !j.link) continue;
    index[normalize(j.link)] = { wp_id: j.id, wp_type: restBase, last_modified: String(j.modified ?? '').slice(0, 10) };
  }
}

return $('Identify Decaying Pages').all().map((item, i) => {
  const match = index[item.json.path] ?? { wp_id: '', wp_type: '', last_modified: '' };
  return { json: { ...item.json, ...match }, pairedItem: { item: i } };
});

// Compare queries between the two windows for this page.
const current = $('Post Current Period Queries').item.json.rows ?? [];
const previous = $('Post Previous Period Queries').item.json.rows ?? [];

const map = {};
for (const r of previous) {
  map[r.keys[0]] = { q: r.keys[0], pc: r.clicks, pi: r.impressions, pp: r.position, cc: 0, ci: 0, cp: null };
}
for (const r of current) {
  const e = map[r.keys[0]] ?? (map[r.keys[0]] = { q: r.keys[0], pc: 0, pi: 0, pp: null });
  e.cc = r.clicks; e.ci = r.impressions; e.cp = r.position;
}

const all = Object.values(map);
const pos = (v) => (v == null ? '-' : v.toFixed(1));
const line = (e) => `${e.q}: clicks ${e.pc} -> ${e.cc}, impressions ${e.pi} -> ${e.ci}, position ${pos(e.pp)} -> ${pos(e.cp)}`;

const lost = all
  .filter((e) => e.cc < e.pc)
  .sort((a, b) => (b.pc - b.cc) - (a.pc - a.cc))
  .slice(0, 8);
const gained = all
  .filter((e) => (e.pi === 0 && e.ci > 0) || e.cc > e.pc)
  .sort((a, b) => (b.ci - b.pi) - (a.ci - a.pi))
  .slice(0, 5);

return {
  json: {
    ...$('Match WP Page IDs').item.json,
    lost_queries: lost.map((e) => e.q).join(' / '),
    new_queries: gained.map((e) => e.q).join(' / '),
    lost_queries_detail: lost.map(line).join('\n'),
    new_queries_detail: gained.map(line).join('\n'),
  },
};

// Turn the WordPress content (or live HTML) into headings + plain text for the prompt.
const cfg = $('Set GSC and WP Config').first().json;
const page = $('Analyze Query Changes').item.json;
const html = String($json.content?.rendered ?? $json.html ?? '');

const strip = (s) => String(s)
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ')
  .trim();

const headings = [...html.matchAll(/<h([23])[^>]*>([\s\S]*?)<\/h\1>/gi)]
  .map((m) => `H${m[1]}: ${strip(m[2])}`)
  .filter((h) => h.length > 4)
  .slice(0, 40);

const text = strip(html
  .replace(/<head[\s\S]*?<\/head>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<(nav|header|footer|aside)[\s\S]*?<\/\1>/gi, ' '));

const title = strip($json.title?.rendered ?? html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] ?? '');

return {
  json: {
    ...page,
    article_title: title,
    last_modified: page.last_modified || String($json.modified ?? '').slice(0, 10),
    headings: headings.join('\n'),
    article_text: text.slice(0, Number(cfg.max_article_chars)),
    article_truncated: text.length > Number(cfg.max_article_chars),
  },
};

parameters.text:
=You are reviewing a page that is losing Google search traffic. Write a practical refresh brief for the person who will update it.

Output language: {{ $('Set GSC and WP Config').first().json.language }}
URL: {{ $json.page_url }}
Title: {{ $json.article_title || '(unknown)' }}
Last modified: {{ $json.last_modified || 'unknown' }} (today is {{ $today.toFormat('yyyy-MM-dd') }})

Clicks: {{ $json.clicks_prev }} -> {{ $json.clicks_now }} ({{ $json.click_change }}) over two {{ $('Set GSC and WP Config').first().json.compare_days }}-day windows. Impressions: {{ $json.impressions_prev }} -> {{ $json.impressions_now }}. Average position: {{ $json.position_prev }} -> {{ $json.position_now || 'not ranking' }}.

Queries that lost clicks (previous -> current):
{{ $json.lost_queries_detail || '(none)' }}

New or growing queries:
{{ $json.new_queries_detail || '(none)' }}

Current headings:
{{ $json.headings || '(none found)' }}

Article text{{ $json.article_truncated ? ' (truncated)' : '' }}:
{{ $json.article_text || '(not available)' }}

Instructions:
- Diagnose the most likely reason for the drop from the evidence: falling position vs. falling CTR, lost queries, outdated information, missing subtopics, or intent mismatch.
- If impressions held steady but clicks fell, treat it as a CTR problem (title, snippet or SERP features). If impressions fell, treat it as a ranking or demand problem.
- Every action must be specific to this article, for example which section to update and with what, which lost query to answer and where. No generic SEO advice.
- Only refer to facts in the article or the data above. Do not invent statistics, dates or product details. Flag information that looks outdated instead of rewriting it.
- priority: high if lost clicks are large or the page is clearly outdated, otherwise medium or low.

