// Find rows the user marked as refreshed: stamp a date, or measure once enough data exists.
const cfg = $('Set GSC and WP Config').first().json;
const N = Number(cfg.compare_days);
const DAY = 86400000;
const fmt = (ms) => new Date(ms).toISOString().slice(0, 10);
const today = Date.parse(fmt(Date.now()));
const dataEnd = today - 3 * DAY; // Search Console data lags about 2-3 days

const out = [];
$('Read Log from Google Sheets').all().forEach((row, i) => {
  const j = row.json;
  if (String(j.status ?? '').trim().toLowerCase() !== 'refreshed' || !j.row_number) return;

  const raw = String(j.refreshed_at ?? '').trim().replace(/\//g, '-');
  if (!raw) {
    out.push({ json: { action: 'stamp', row_number: j.row_number, refreshed_at: fmt(today) }, pairedItem: { item: i } });
    return;
  }

  const refreshed = Date.parse(raw.slice(0, 10));
  if (isNaN(refreshed) || refreshed + N * DAY > dataEnd) return; // wait for a full post-refresh window

  out.push({
    json: {
      action: 'measure',
      row_number: j.row_number,
      page_url: j.page_url,
      refreshed_at: fmt(refreshed),
      start: fmt(refreshed - N * DAY),
      end: fmt(refreshed + N * DAY),
    },
    pairedItem: { item: i },
  });
});

return out;

// Compare clicks in the window before vs. after the refresh date (refresh day excluded).
const cfg = $('Set GSC and WP Config').first().json;
const N = Number(cfg.compare_days);
const DAY = 86400000;
const src = $('Label Refreshed Rows').item.json;
const refreshed = Date.parse(src.refreshed_at);

let before = 0;
let after = 0;
for (const r of $json.rows ?? []) {
  const d = Date.parse(r.keys[0]);
  if (d < refreshed && d >= refreshed - N * DAY) before += r.clicks;
  else if (d > refreshed && d <= refreshed + N * DAY) after += r.clicks;
}

const change = before > 0 ? (after - before) / before : null;
return {
  json: {
    row_number: src.row_number,
    clicks_before: before,
    clicks_after: after,
    refresh_result: change === null ? 'n/a (no clicks before)' : `${change >= 0 ? '+' : ''}${(change * 100).toFixed(1)}%`,
  },
};
